//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    players: Arc<Mutex<HashMap<PlayerId, Arc<Mutex<i64>>>>>,
    total: Arc<Mutex<i64>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        self.players.lock().unwrap().insert(id, Arc::new(Mutex::new(score)));
        *self.total.lock().unwrap() += score;
    }

    fn slot(&self, id: PlayerId) -> Arc<Mutex<i64>> {
        self.players.lock().unwrap()[&id].clone()
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        // Hold each lock across the whole read-modify-write; the earlier
        // read-unlock-write sequence lost concurrent awards.
        let slot = self.slot(id);
        *slot.lock().unwrap() += points;
        *self.total.lock().unwrap() += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            // Locking the same slot twice would self-deadlock.
            return;
        }
        let from_slot = self.slot(from);
        let to_slot = self.slot(to);
        // Lock in a fixed global order (lower id first) so transfer(a, b)
        // racing transfer(b, a) cannot deadlock.
        let (first, second) = if from < to {
            (&from_slot, &to_slot)
        } else {
            (&to_slot, &from_slot)
        };
        let mut first_score = first.lock().unwrap();
        let mut second_score = second.lock().unwrap();
        let (from_score, to_score) = if from < to {
            (&mut *first_score, &mut *second_score)
        } else {
            (&mut *second_score, &mut *first_score)
        };
        *from_score -= points;
        *to_score += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self.slot(id).lock().unwrap()
    }

    pub fn total(&self) -> i64 {
        *self.total.lock().unwrap()
    }
}

#[cfg(test)]
mod concurrency_regression {
    use super::Board;
    use std::thread;

    #[test]
    fn parallel_awards_keep_every_point() {
        let board = Board::new();
        board.join(1, 0);
        let handles: Vec<_> = (0..8)
            .map(|_| {
                let b = board.clone();
                thread::spawn(move || {
                    for _ in 0..10_000 {
                        b.award(1, 1);
                    }
                })
            })
            .collect();
        for h in handles {
            h.join().unwrap();
        }
        assert_eq!((board.score(1), board.total()), (80_000, 80_000));
    }

    #[test]
    fn opposite_transfers_and_self_transfer_do_not_hang() {
        let board = Board::new();
        board.join(1, 1_000_000);
        board.join(2, 1_000_000);
        board.transfer(1, 1, 5);
        let a = {
            let b = board.clone();
            thread::spawn(move || {
                for _ in 0..50_000 {
                    b.transfer(1, 2, 1);
                }
            })
        };
        let b2 = {
            let b = board.clone();
            thread::spawn(move || {
                for _ in 0..50_000 {
                    b.transfer(2, 1, 1);
                }
            })
        };
        a.join().unwrap();
        b2.join().unwrap();
        assert_eq!(
            (board.score(1), board.score(2), board.total()),
            (1_000_000, 1_000_000, 2_000_000)
        );
    }
}
